def get_episode_bounds(episode_ends: np.ndarray) -> np.ndarray:
    """Return inclusive-exclusive timestep bounds for each episode."""
    starts = np.concatenate(([0], episode_ends[:-1]))
    return np.stack((starts, episode_ends), axis=1)

